SELECT 
FROM t_delivery
WHERE 1 = 1

    AND tran_id = #{query.tranId}


    AND customer_id = #{query.customerId}


    AND vehicle_id = #{query.vehicleId}


    AND responsible_user_id = #{query.responsibleUserId}


    AND status = #{query.status}

ORDER BY planned_delivery_time DESC, id DESC

